const d = JSON.parse($json.message?.content || '{}');
const errors = [];
if (!d.cliente_cnpj) errors.push('R1: CNPJ faltante');
if (!d.cliente_razao) errors.push('R3: Razon social faltante');
if (!d.ie) errors.push('R2: IE faltante');
if (!d.direccion) errors.push('R4: Direccion faltante');
if (!d.produto_codigo) errors.push('R5: Codigo de producto faltante');
if (!d.quantidade || d.quantidade <= 0) errors.push('R6: Cantidad invalida');
if (!d.valor_unit || d.valor_unit <= 0) errors.push('R6: Valor unitario invalido');
if (!['30','60','90'].includes(String(d.condicao_pagamento))) errors.push('R7: Condicion de pago invalida');
if (!['CIF','FOB'].includes(String(d.cif_fob))) errors.push('R8: CIF/FOB invalido');
const status = errors.length === 0 ? 'Validado' : 'Excecao';
const prioridad = (d.valor_total > 50000) ? 'Urgente' : (d.valor_total > 10000) ? 'Alta' : 'Normal';
return [{ json: { ...d, status, prioridad, errors } }];
